 if(d.type==='season_done'&&room.phase==='simulating'&&!p.ended&&validGateMessage(d)&&p.seasonReadyFor===room.season){if(p.seasonDoneFor===room.season)return;const result=sanitizeSeasonResult(d.result,p);room.seasonResults.push(result);p.seasonDoneFor=room.season;p.ended=!!result.ended;p.careerName=result.careerName||p.careerName;if(p.careerName)p.name=p.careerName;p.position=room.settings.position;p.rarity=effectiveRarity();p.club=result.nextClub||result.club||p.club;p.ovr=result.ovr||p.ovr;if(result.legacyScore)p.legacyScore=result.legacyScore;p.lastSeenAt=Date.now();publish();if(allSeasonDone())finalizeSeasonWorld();return}
