function syncReadyHeartbeat(){if(!room)return;const now=Date.now(),me=roomPlayer();if(!isHost&&hostConn?.open&&now-lastPresenceHeartbeat>3500){lastPresenceHeartbeat=now;safeSend(hostConn,{type:'presence',gameNo:room.gameNo,season:room.season})}if(room.phase==='career_setup'&&localCareerReady&&state&&me&&!me.careerReady&&now-lastCareerHeartbeat>900){lastCareerHeartbeat=now;sendHost('career_ready',{gameNo:room.gameNo,careerName:state.player.name,position:state.player.position,rarity:state.player.rarity,club:state.player.club,ovr:state.player.rating})}if(room.phase==='playing'&&state&&!state.ended&&localSeasonReadyFor===room.season&&me?.seasonReadyFor!==room.season&&now-lastReadyHeartbeat>900){lastReadyHeartbeat=now;sendHost('season_ready',{season:room.season,gameNo:room.gameNo,gate:gateTag()})}if(room.phase==='review'&&reviewReady&&me?.revealReadyFor!==room.season&&now-lastReviewHeartbeat>900){lastReviewHeartbeat=now;sendHost('reveal_ready',{season:room.season,gameNo:room.gameNo,gate:gateTag()})}if(room.phase==='final_review'&&me?.finalReadyFor===room.gameNo&&now-lastFinalHeartbeat>900){lastFinalHeartbeat=now;sendHost('final_ready',{gameNo:room.gameNo})}if(isHost){const host=roomPlayer();if(host){host.lastSeenAt=now;host.connected=true}checkPresenceTimeouts();checkGates();updateDisconnectControls()}}
