playSeasonUI=function(){if(!room||room.phase!=='playing')return mpToast('This season is locked until the whole party reaches the same stage.');const me=roomPlayer();if(!me||me.ended)return;if(state?.pendingOffers?.length){activeTab='journey';mpToast(`Resolve your ${state.pendingOffers.length} transfer offer${state.pendingOffers.length===1?'':'s'} before simulating the season.`);return}if(state?.pendingStory){activeTab='journey';mpToast('Make your decision before simulating the season.');return}if(me.seasonReadyFor===room.season||localSeasonReadyFor===room.season)return mpToast('You are already ready for this season.');localSeasonReadyFor=room.season;lastReadyHeartbeat=Date.now();sendHost('season_ready',{season:room.season,gameNo:room.gameNo,gate:gateTag()});mpToast('Ready. The season starts for everyone only when everyone is ready.');setTimeout(renderAll,30)};
