 let finalGate=$('#mpFinalReviewGate');if(room.phase==='final_review'){if(!finalGate){const tabs=$('#tabs');tabs?.insertAdjacentHTML('afterend',`<section class="panel mpFinalReviewGate" id="mpFinalReviewGate"><div><div class="eyebrow">FINAL LEADERBOARD • SEALED</div><h3>Review your Legacy before the podium.</h3><p>Open Legacy and look through your career progress, route, honours and final Legacy score. The podium will not begin until everyone presses Ready.</p></div><div class="mpFinalReviewActions"><button class="secondary" id="mpOpenLegacy">View Legacy & Progress</button><button class="primary" id="mpFinalReady" ${me?.finalReadyFor===room.gameNo?'disabled':''}>${me?.finalReadyFor===room.gameNo?'✓ Ready — waiting for everyone':'Ready for Final Leaderboard'}</button></div></section>`);finalGate=$('#mpFinalReviewGate');$('#mpOpenLegacy')?.addEventListener('click',()=>{$('#tabs [data-tab="legacy"]')?.click();setTimeout(()=>$('#tab-legacy')?.scrollIntoView({behavior:'smooth',block:'start'}),80)});$('#mpFinalReady')?.addEventListener('click',setFinalReady)}}else finalGate?.remove();
 if(me?.ended&&room.phase==='playing'&&!$('.mpRetiredWait'))$('.quickActionCard')?.insertAdjacentHTML('afterend','<section class="panel mpRetiredWait"><div class="eyebrow">CAREER COMPLETE</div><h3>Your points are locked.</h3><p>You can browse Legacy while the remaining careers continue. You are automatically counted as ready each season.</p></section>');
