function rankMovement(oldR,newR){if(newR<oldR)return `<span class="mpMove up">▲${oldR-newR}</span>`;if(newR>oldR)return `<span class="mpMove down">▼${newR-oldR}</span>`;return '<span class="mpMove same">•</span>'}
function leaderboardRows(){const prev=room.previousRanks||{},current={};[...room.players].sort((a,b)=>b.totalPoints-a.totalPoints||a.name.localeCompare(b.name)).forEach((p,i)=>current[p.id]=i+1);const old=[...room.players].sort((a,b)=>(prev[a.id]||99)-(prev[b.id]||99)||a.name.localeCompare(b.name));return old.map(p=>{const before=p.totalPoints-p.lastSeasonPoints;return `<div class="mpScoreRow ${p.id===myId?'you':''}" data-id="${mpEsc(p.id)}" data-old="${prev[p.id]||current[p.id]}" data-new="${current[p.id]}" data-before="${before}" data-after="${p.totalPoints}" data-gain="${p.lastSeasonPoints}"><div class="mpScoreRank"><strong>${prev[p.id]||current[p.id]}</strong><span class="mpMove same">•</span></div><div class="mpScoreIdentity"><b>${mpEsc(p.name)}${p.id===myId?' • You':''}</b><small>${mpEsc(p.careerName||p.club||'Career')} ${p.ended?'• Retired':''}</small></div><div class="mpSeasonGain"><span>+0</span><small>THIS SEASON</small></div><div class="mpScoreTick"><span>${before.toLocaleString()}</span><i>+</i><strong>${before.toLocaleString()}</strong></div></div>`}).join('')}
async function flipRanks(run){const list=$('#mpScoreList'),rows=list?[...list.children]:[];if(!list)return;const first=new Map(rows.map(r=>[r,r.getBoundingClientRect().top]));rows.sort((a,b)=>+a.dataset.new-+b.dataset.new).forEach(r=>list.appendChild(r));const last=new Map(rows.map(r=>[r,r.getBoundingClientRect().top]));for(const r of rows){const dy=(first.get(r)||0)-(last.get(r)||0);r.style.transition='none';r.style.transform=`translateY(${dy}px)`;r.querySelector('.mpScoreRank strong').textContent=r.dataset.new;r.querySelector('.mpMove').outerHTML=rankMovement(+r.dataset.old,+r.dataset.new)}void list.offsetHeight;for(const r of rows){r.style.transition=reduced()?'none':'transform 900ms cubic-bezier(.2,.82,.2,1)';r.style.transform='translateY(0)'}await sleep(reduced()?20:960);if(run!==cinematicRun)return;rows.forEach((r,i)=>{r.style.transition='';r.style.transform='';if(i===0)r.classList.add('leader')})}
async function showLeaderboard(){const run=++cinematicRun,el=overlayRoot(),winner=seasonWinnerResult();if(!winner)return;overlayHeld=true;const careersComplete=allEnded();el.innerHTML=`<div class="mpCineShell"><div class="mpCineTop"><div><div class="eyebrow">SEASON ${room.season} COMPLETE</div><h1>${mpEsc(winner.name)} won the season.</h1><p>${careersComplete?'After this update, everyone gets time to inspect Legacy and career progress before the final podium.':'Now the career leaderboard updates.'}</p></div><div class="mpSealedBox"><small>OVERALL LEADER</small><strong id="mpOverallLeader">•••</strong></div></div><div class="mpCineCard"><div class="eyebrow">OVERALL GAME LEADERBOARD</div><div class="mpLeaderboardStatus" id="mpLeaderStatus">Loading the previous table…</div><div class="mpScoreList" id="mpScoreList">${leaderboardRows()}</div><div class="mpContinueWrap" id="mpContinueWrap"><button class="secondary" id="mpViewSeasonReview">View Season Review</button>${careersComplete?'<div class="mpWaiting">Career review opens next — final podium remains sealed.</div>':'<button class="primary" id="mpContinueCareer">Continue Your Career</button>'}</div></div></div>`;await sleep(reduced()?20:450);$('#mpLeaderStatus').textContent='Adding this season’s points…';const rows=$$('#mpScoreList .mpScoreRow');await Promise.all(rows.map(async(r,i)=>{await sleep(reduced()?0:i*80);const gain=+r.dataset.gain,before=+r.dataset.before,after=+r.dataset.after;await Promise.all([animateNum(r.querySelector('.mpSeasonGain span'),0,gain,reduced()?0:1050,run,'+'),animateNum(r.querySelector('.mpScoreTick strong'),before,after,reduced()?0:1400,run)])}));if(run!==cinematicRun)return;$('#mpLeaderStatus').textContent='Recalculating the order…';await sleep(reduced()?20:380);await flipRanks(run);if(run!==cinematicRun)return;const leader=[...room.players].sort((a,b)=>b.totalPoints-a.totalPoints||a.name.localeCompare(b.name))[0];$('#mpOverallLeader').textContent=mpInitials(leader.name);$('#mpLeaderStatus').textContent=`${leader.name} leads with ${leader.totalPoints.toLocaleString()} points.`;$('#mpContinueWrap').classList.add('show');$('#mpViewSeasonReview')?.addEventListener('click',openPostPointsReview);$('#mpContinueCareer')?.addEventListener('click',()=>{overlayHeld=false;window.FL_MP_BALLON_REVEALED=false;reviewReady=false;reviewAvailable=false;pendingSeason=null;pendingDelta=0;localReviewFinalizedKey='';$('#mpSharedOverlay')?.remove();activeTab='journey';renderAll();scrollTo({top:0,behavior:'smooth'})});await sleep(reduced()?20:700);if(isHost&&room.phase==='leaderboard'){if(allEnded()){room.phase='final_review';room.players.forEach(p=>p.finalReadyFor=0);publish()}else{room.season++;room.phase='playing';room.seasonResults=[];room.previousRanks=currentRankMap();room.simulationAt=0;room.simulationKey='';room.revealAt=0;room.revealKey='';room.ballonWinnerId=null;room.ballonReveal=null;room.ballonRevealAt=0;room.ballonRevealKey='';room.players.forEach(p=>{p.seasonReady=!!p.ended;p.seasonReadyFor=p.ended?room.season:0;p.seasonDoneFor=0;p.revealReady=false;p.revealReadyFor=0;p.ballonRevealReadyFor=0;p.finalReadyFor=0;p.preSeasonEnded=!!p.ended;p.lastSeasonPoints=0});localSeasonReadyFor=0;publish()}}}
