function showLobby(){if(!room)return;$('#mpEntry')?.remove();hideReconnectPanel();let el=$('#mpLobbyOverlay');if(!el){el=document.createElement('div');el.id='mpLobbyOverlay';el.className='mpLobbyOverlay';document.body.appendChild(el)}const pos=room.settings?.position||'ST',rarity=room.settings?.rarity||'common',posOptions=POSITIONS.map(x=>`<option value="${x}" ${x===pos?'selected':''}>${mpEsc(POS_LABEL[x]||x)}</option>`).join(''),rarityOptions=['common','uncommon','rare','epic','legendary','mythic','ungodly','random'].map(x=>`<option value="${x}" ${x===rarity?'selected':''}>${x==='random'?'? Mystery Rarity':x.charAt(0).toUpperCase()+x.slice(1)}</option>`).join(''),rarityCopy=rarity==='random'?'Mystery Rarity • the shared rarity stays sealed until the careers are generated':`${rarityLabel(rarity)} rarity`;el.innerHTML=`<div class="mpOverlayShell"><div class="mpOverlayBrand"><a href="index.html#modes"><span class="logo">FL</span></a><span class="mpRoomMark">WAITING ROOM</span></div><div class="mpLobbyHead"><div><div class="eyebrow">PLAY WITH FRIENDS</div><h1>${room.players.length} of ${MAX_PLAYERS} players</h1></div><button class="mpCode" id="mpCopyCode"><small>TAP TO COPY</small><strong>${room.code}</strong></button></div><section class="panel mpLobbyPanel"><div class="eyebrow">PARTY • JOIN ORDER</div><div class="mpPlayers">${room.players.slice().sort((a,b)=>(a.joinOrder||0)-(b.joinOrder||0)).map((p,i)=>`<div class="mpPlayerTile"><div class="mpAvatar">${mpEsc(mpInitials(p.name))}</div><div><b>${i+1}. ${mpEsc(p.name)}${p.id===myId?' • You':''}</b><small>${p.id===room.players[0].id?'HOST • ':''}${p.connected===false?'TEMPORARILY AWAY • SLOT SAVED':'CONNECTED'}</small></div><i class="mpReadyDot ${p.connected!==false?'on':''}"></i></div>`).join('')}</div>${isHost?`<div class="mpSharedSetup"><div><div class="eyebrow">HOST-LOCKED PLAYER RULES</div><h3>Same rarity. Same position. Different careers.</h3><p>Choose Mystery Rarity if you want the rarity itself to be a sealed surprise. Everyone will still receive exactly the same rarity.</p></div><div class="mpSharedSetupGrid"><label>Position<select id="mpSharedPosition">${posOptions}</select></label><label>Rarity<select id="mpSharedRarity">${rarityOptions}</select><small>${mpEsc(rarityCopy)}</small></label></div></div><button class="primary" id="mpStart" ${room.players.length<2||room.players.some(p=>p.connected===false)?'disabled':''}>Start Quick Story Careers</button>`:`<div class="mpSharedSetup locked"><div><div class="eyebrow">HOST-LOCKED PLAYER RULES</div><h3>${mpEsc(POS_LABEL[pos]||pos)} • ${mpEsc(rarityCopy)}</h3><p>Everyone gets the same position, rarity, starting age, starting OVR and retirement age. If Mystery Rarity is selected, nobody sees the rarity until the game begins.</p></div></div><div class="mpWaiting">Waiting for the host to start the shared Quick Story careers.</div>`}</section></div>`;$('#mpCopyCode').onclick=()=>navigator.clipboard?.writeText(room.code).then(()=>mpToast('Room code copied.')).catch(()=>mpToast('Room code: '+room.code));if(isHost){$('#mpSharedPosition')?.addEventListener('change',e=>{if(room.phase!=='lobby')return;room.settings.position=POSITIONS.includes(e.target.value)?e.target.value:'ST';publish()});$('#mpSharedRarity')?.addEventListener('change',e=>{if(room.phase!=='lobby')return;const allowed=['common','uncommon','rare','epic','legendary','mythic','ungodly','random'];room.settings.rarity=allowed.includes(e.target.value)?e.target.value:'common';room.settings.resolvedRarity=room.settings.rarity==='random'?'':room.settings.rarity;publish()})}$('#mpStart')?.addEventListener('click',startParty)}

function resumeHostParty(session,savedRoom){isHost=true;nickname=mpClean(session.careerName||session.nickname)||'Host';reconnectToken=String(session.token||ensureReconnectToken());peer=new Peer(mpPeerId(session.code));installPeerResilience(peer);peer.on('open',id=>{myId=id;room=savedRoom;room.settings=room.settings||{};room.players=(room.players||[]).map((p,i)=>({...p,joinOrder:Number.isFinite(Number(p.joinOrder))?p.joinOrder:i,finalReadyFor:p.finalReadyFor||0,legacyScore:Number(p.legacyScore)||0}));const host=room.players?.[0];if(!host)return showEntry();const oldId=host.id;host.id=myId;host.connected=true;host.disconnectedAt=0;host.lastSeenAt=Date.now();host.reconnectToken=reconnectToken;if(oldId!==myId){for(const r of room.seasonResults||[])if(r.id===oldId)r.id=myId;if(room.ballonWinnerId===oldId)room.ballonWinnerId=myId;if(room.ballonReveal?.id===oldId)room.ballonReveal.id=myId;if(room.previousRanks&&Object.prototype.hasOwnProperty.call(room.previousRanks,oldId)){room.previousRanks[myId]=room.previousRanks[oldId];delete room.previousRanks[oldId]}}const now=Date.now();for(const p of room.players.slice(1)){p.connected=false;p.disconnectedAt=now;p.lastSeenAt=0}state=load()||state;openCompatibilityHosts(session.code);renderRoom(room);publish();mpToast('Party restored — friends can reclaim their saved slots.')});peer.on('error',()=>{showEntry();mpToast('Could not restore the previous host room yet. Try again.')})}
function init(){const session=loadPartySession(),savedHost=session?.role==='host'?loadHostRoom():null;if(session?.role==='host'&&session.code&&savedHost?.code===session.code)resumeHostParty(session,savedHost);else if(session?.role==='client'&&session.code&&session.token){nickname=mpClean(session.careerName||session.nickname)||loadFootballerName()||'Player';reconnectToken=String(session.token);state=load()||state;showReconnectPanel('Your previous multiplayer slot is saved. Restoring it now…');resumeClientParty()}else showEntry();setInterval(syncReadyHeartbeat,1200);const modal=$('#modal');modal?.addEventListener('click',e=>{if(e.target===modal){e.preventDefault();e.stopImmediatePropagation();return}if(e.target.closest?.('[data-new]')&&room){e.preventDefault();e.stopImmediatePropagation();mpToast('Use Play Again With Same Party after the final result.') }},true);document.addEventListener('click',e=>{const b=e.target.closest?.('[data-mp-honour-continue],button[id^="mpV8-"]');if(!b||typeof honourAdvance!=='function')return;e.preventDefault();e.stopPropagation();const fn=honourAdvance;honourAdvance=null;fn()},true);const recover=()=>{if(document.visibilityState==='visible')recoverConnectionNow()};document.addEventListener('visibilitychange',recover);window.addEventListener('pageshow',recover);window.addEventListener('focus',recover);window.addEventListener('online',recover)}
