function qaRun(){const fail=[],careers=[];try{const keepRoom=room;room={code:'QA-RULES',gameNo:3,phase:'career_setup',season:4,settings:{position:'CM',rarity:'rare',startAge:17,startOvr:60,retirementAge:37},players:[],seasonResults:[],previousRanks:{}};for(let i=0;i<6;i++){const st=createCareerForRoom(`MP-QA-${i}`),moves=[];if(st.player.position!=='CM')fail.push('shared position not enforced');if(st.player.rarity!=='rare')fail.push('shared rarity not enforced');if(st.player.age!==17)fail.push('shared starting age not enforced');if(st.player.rating!==60)fail.push('shared starting overall not enforced');if(st.player.retirementAge!==37)fail.push('shared retirement age not enforced');for(let y=0;y<12&&!st.ended;y++){if(st.pendingOffers.length){const best=st.pendingOffers.map((o,j)=>({o,j})).sort((a,b)=>b.o.fit-a.o.fit)[0];if(best?.o.fit>=62){moves.push(y+1);acceptOffer(st,best.j)}else stayPut(st)}if(st.pendingStory){storyModifier(st,(i+y)%3);st.storyDecisionReady=null}simulateSeason(st,null)}careers.push({name:st.player.name,start:st.transfers[0]?.to,club:st.player.club,ovr:st.player.rating,moves,seasons:st.history.length,position:st.player.position,rarity:st.player.rarity})}for(const pos of POSITIONS)for(const rarity of ['common','uncommon','rare','epic','legendary','mythic']){room.settings={position:pos,rarity};const st=createCareerForRoom(`RULE-${pos}-${rarity}`);if(st.player.position!==pos)fail.push(`position rule failed: ${pos}`);if(st.player.rarity!==rarity)fail.push(`rarity rule failed: ${rarity}`)}room.settings={position:'CM',rarity:'rare'};if(new Set(careers.map(x=>x.name+'|'+x.start)).size<4)fail.push('careers are not sufficiently distinct');if(new Set(careers.map(x=>x.moves.join(','))).size<2)fail.push('transfer timing did not diverge');room={code:'QA-GATE',gameNo:7,phase:'playing',season:5,settings:{position:'ST',rarity:'common'},players:[makeRoomPlayer('a','A'),makeRoomPlayer('b','B')],seasonResults:[],previousRanks:{}};room.players.forEach(p=>{p.careerReady=true});room.players[0].seasonReadyFor=5;room.players[0].seasonReady=true;if(allSeasonReady())fail.push('gate opened before everyone was ready');room.players[1].connected=false;room.players[1].seasonReadyFor=5;room.players[1].seasonReady=true;if(allSeasonReady())fail.push('disconnected player was silently ignored by gate');room.players[1].connected=true;if(!allSeasonReady())fail.push('gate did not open when both players were ready for exact season');room.players[1].seasonReadyFor=4;if(allSeasonReady())fail.push('stale ready from previous season opened gate');isHost=true;room.players[1].seasonReadyFor=0;room.players[0].seasonReadyFor=0;handleHostMessage({peer:'a'},{type:'season_ready',gameNo:7,season:5},true);if(room.phase!=='playing')fail.push('host advanced after only one ready message');handleHostMessage({peer:'b'},{type:'season_ready',gameNo:7,season:4},false);if(room.phase!=='playing')fail.push('stale season ready advanced host');handleHostMessage({peer:'b'},{type:'season_ready',gameNo:7,season:5},false);if(room.phase!=='simulating')fail.push(`exact two-player ready barrier did not open: phase=${room.phase}`);isHost=false;room.phase='review';room.season=5;room.players.forEach(p=>{p.preSeasonEnded=false;p.revealReady=false;p.revealReadyFor=0;p.connected=true});room.players[0].revealReadyFor=5;if(allRevealReady())fail.push('points gate opened before everyone was ready');room.players[1].connected=false;room.players[1].revealReadyFor=5;if(allRevealReady())fail.push('disconnected player was ignored by points gate');room.players[1].connected=true;if(!allRevealReady())fail.push('points gate did not open for exact season');room.players[1].revealReadyFor=4;if(allRevealReady())fail.push('stale reveal-ready opened points gate');const sample={goals:4,assists:3,league:'Premier League',trophies:['Premier League','FA Cup','Champions League','World Cup'],awards:["Ballon d'Or",'Premier League Player of the Season'],ballonDor:true},parts=scoreParts(sample),total=Object.values(parts).reduce((a,b)=>a+b,0);if(parts.goals!==40||parts.assists!==30||parts.league!==500||parts.domestic!==250||parts.continental!==800||parts.international!==1100||parts.awards!==300||parts.ballon!==1200)fail.push('point categories mismatch');if(total!==4220)fail.push(`point total mismatch: ${total}`);room={code:'QA-BALLON',gameNo:1,season:1};const candidates=Array.from({length:6},(_,i)=>({id:`p${i}`,participated:true,ballonEligible:true,ballonScore:100-i,ballonRank:i===0?1:i+1,ballonProb:i===0?1:0}));for(let season=1;season<=100;season++){room.season=season;const winner=chooseBallonWinner(candidates);if(winner!=='p0')fail.push('rank-1 Ballon player did not win shared award')}/* V104.7 reconnection identity: an active disconnected slot can be reclaimed by token. */room={code:'QA-REJOIN',gameNo:1,phase:'playing',season:2,settings:{position:'ST',rarity:'common'},players:[makeRoomPlayer('host','Host','host-token'),makeRoomPlayer('old-peer','Friend','friend-token')],seasonResults:[],previousRanks:{}};room.players[1].connected=false;room.players[1].disconnectedAt=Date.now()-25000;isHost=true;handleHostMessage({peer:'new-peer',send:()=>{}},{type:'join',protocol:PROTOCOL,reconnectToken:'friend-token',name:'Friend'},false);if(!room.players.some(p=>p.id==='new-peer'&&p.connected))fail.push('reconnect token did not reclaim disconnected slot');room.players[1].connected=false;room.players[1].disconnectedAt=Date.now()-DISCONNECT_GRACE-1000;removeDisconnectedPlayer('new-peer');if(room.players.some(p=>p.id==='new-peer'))fail.push('host removal did not clear disconnected player');room={code:'QA-MYSTERY',gameNo:2,phase:'lobby',season:1,settings:{position:'AM',rarity:'random',resolvedRarity:''},players:[makeRoomPlayer('a','A','',0),makeRoomPlayer('b','B','',1)],seasonResults:[],previousRanks:{}};const mystery=resolveSharedRarity();if(!['common','uncommon','rare','epic','legendary','mythic','ungodly'].includes(mystery))fail.push('mystery rarity did not resolve');if(effectiveRarity()!==mystery)fail.push('mystery rarity not shared');room.phase='final_review';room.gameNo=9;room.players.forEach(p=>{p.connected=true;p.finalReadyFor=0});room.players[0].finalReadyFor=9;if(allFinalReady())fail.push('final leaderboard opened before all players were ready');room.players[1].finalReadyFor=9;if(!allFinalReady())fail.push('final leaderboard gate did not open for all ready players');room.seasonResults=[{id:'b',seasonPoints:900,avg:7.5,goals:8,assists:5},{id:'a',seasonPoints:1200,avg:8,goals:10,assists:10}];const joinOrdered=seasonResultsInJoinOrder();if(joinOrdered[0]?.id!=='a'||joinOrdered[1]?.id!=='b')fail.push('points reveal did not preserve join order');room=keepRoom}catch(e){fail.push(e.stack||String(e))}return {ok:!fail.length,fail,careers}};

function protocolQaRun(){
 const fail=[],keep={room,isHost,myId,state,localSeasonReadyFor,localScheduledSimulationKey,localCompletedSimulationKey,localReviewFinalizedKey,breakdownRunKey,ballonRevealRunKey};
 try{
  isHost=true;myId='host';state=null;localSeasonReadyFor=0;localScheduledSimulationKey='';localCompletedSimulationKey='';localReviewFinalizedKey='';breakdownRunKey='';
  room={code:'SYNC6',gameNo:2,phase:'playing',season:3,settings:{position:'ST',rarity:'rare'},players:[makeRoomPlayer('host','Host'),makeRoomPlayer('friend','Friend')],seasonResults:[],previousRanks:{}};
  room.players.forEach(p=>{p.careerReady=true;p.connected=true;p.club='Test FC';p.ovr=70});
  handleHostMessage({peer:'host'},{type:'season_ready',gameNo:2,season:3},true);
  if(room.phase!=='playing')fail.push('one player unlocked simulation');
  handleHostMessage({peer:'friend'},{type:'season_ready',gameNo:2,season:2},false);
  if(room.phase!=='playing')fail.push('stale season ready unlocked simulation');
  handleHostMessage({peer:'friend'},{type:'season_ready',gameNo:2,season:3},false);
  if(room.phase!=='simulating')fail.push('all ready did not enter synchronized simulation');
  if(!(room.simulationAt>Date.now()))fail.push('synchronized simulation has no future start time');
  if(room.seasonResults.length)fail.push('a season simulated before the synchronized start/result messages');
  const base={careerName:'Player',position:'ST',club:'Test FC',nextClub:'Test FC',ovr:71,potential:80,ended:false,participated:true,apps:30,goals:10,assists:5,avg:7.1,grade:'B',league:'Test League',leaguePosition:4,trophies:[],awards:[],ballonEligible:false,ballonProb:0,ballonScore:0};
  handleHostMessage({peer:'host'},{type:'season_done',gameNo:2,season:3,result:base},true);
  if(room.phase!=='simulating')fail.push('review opened before every player finished simulation');
  handleHostMessage({peer:'friend'},{type:'season_done',gameNo:2,season:3,result:{...base,goals:7}},false);
  if(room.phase!=='review')fail.push('all completed seasons did not open private review stage');
  handleHostMessage({peer:'host'},{type:'reveal_ready',gameNo:2,season:3},true);
  if(room.phase!=='review')fail.push('one player unlocked points reveal');
  handleHostMessage({peer:'friend'},{type:'reveal_ready',gameNo:2,season:2},false);
  if(room.phase!=='review')fail.push('stale reveal ready unlocked points reveal');
  handleHostMessage({peer:'friend'},{type:'reveal_ready',gameNo:2,season:3},false);
  if(room.phase!=='breakdown')fail.push('all review-ready players did not unlock points reveal');
  if(!(room.revealAt>Date.now()))fail.push('points reveal has no synchronized future start time');
  room.phase='simulating';room.season=4;state=createCareerForRoom('SCENARIO-TIMING-QA');state.pendingStory=null;state.mpScenarioPreparedFor=null;const rngBeforeBlocked=state.rng;if(maybeStory(state)!==null)fail.push('scenario appeared during simulation/review window');if(state.rng!==rngBeforeBlocked)fail.push('blocked scenario changed RNG outside season start');room.phase='playing';const firstScenario=maybeStory(state),preparedTag=state.mpScenarioPreparedFor,rngAfterFirst=state.rng;maybeStory(state);if(preparedTag!==gateTag())fail.push('scenario was not tagged to the exact season start');if(state.rng!==rngAfterFirst)fail.push('scenario rolled more than once in one season');room.phase='review';if(maybeStory(state)!==null)fail.push('scenario appeared during private review');
  room.phase='playing';room.season=4;room.players.forEach(p=>{p.seasonReadyFor=0;p.seasonReady=false});state={pendingOffers:[{club:'X'}],pendingStory:null,ended:false};playSeasonUI();if(room.players[0].seasonReadyFor===4)fail.push('transfer offer did not block season ready');
  state={pendingOffers:[],pendingStory:{title:'Decision'},ended:false};playSeasonUI();if(room.players[0].seasonReadyFor===4)fail.push('scenario did not block season ready');
 }catch(e){fail.push(e.stack||String(e))}
 room=keep.room;isHost=keep.isHost;myId=keep.myId;state=keep.state;localSeasonReadyFor=keep.localSeasonReadyFor;localScheduledSimulationKey=keep.localScheduledSimulationKey;localCompletedSimulationKey=keep.localCompletedSimulationKey;localReviewFinalizedKey=keep.localReviewFinalizedKey;breakdownRunKey=keep.breakdownRunKey;ballonRevealRunKey=keep.ballonRevealRunKey;
 return {ok:!fail.length,fail};
}

window.FL_MULTIPLAYER_QUICK_V8={getRoom:()=>room,points:POINTS,scoreParts,awardValue,qaRun,protocolQaRun,__test:{createRoom,joinRoom,handleHostMessage,handleClientMessage,cleanupPeerSession,mpPeerId,effectiveRarity,resolveSharedRarity,seasonResultsInJoinOrder,seasonWinnerResult,allFinalReady,revealGrid,entryMarkup,reviewFormMarkup,categories:CATS.map(x=>x[0]),disconnectGrace:DISCONNECT_GRACE,presenceTimeout:PRESENCE_TIMEOUT,reviewEmail:REVIEW_EMAIL}};
